mapper.select:
SELECT COUNTER_ID id, COUNTER_NAME text, CASE WHEN COUNTER_TYPE=#{COUNTER_TYPE} THEN #{YES_NO_N} ELSE #{YES_NO_Y} END object FROM MST_COUNTER_PARTY LEFT JOIN MST_CFETS_CUSTOMER_INFO ON MST_COUNTER_PARTY.COUNTER_NAME = MST_CFETS_CUSTOMER_INFO.PARTY_NAME where 1=1
AND not exists (select 1 from PTL_PORTFOLIO p where p.PORTFOLIO_ID = MST_COUNTER_PARTY.COUNTER_ID) and NOT EXISTS (SELECT 1 FROM fin_product p WHERE p.FINPROD_MARKET_ID = MST_COUNTER_PARTY.COUNTER_ID)
AND exists (select 1 from PTL_PORTFOLIO p where p.PORTFOLIO_ID = MST_COUNTER_PARTY.COUNTER_ID)
AND ( MST_COUNTER_PARTY.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR MST_COUNTER_PARTY.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND (MST_COUNTER_PARTY.COUNTER_ID = #{initValue} OR MST_COUNTER_PARTY.COUNTER_NAME = #{initValue})
AND( MST_COUNTER_PARTY.COUNTER_TYPE = #{counterType} OR( MST_COUNTER_PARTY.COUNTER_ID IN
null) or MST_COUNTER_PARTY.COUNTER_ID in (
#{item}
))
AND MST_COUNTER_PARTY.COUNTER_TYPE = #{counterType}

SELECT T1.COUNTER_ID id, T1.COUNTER_NAME text FROM MST_COUNTER_PARTY T1 INNER JOIN MST_CUSTOMER_INFO T2 ON T1.LINK_ID = T2.CUSTOMER_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO T3 ON T1.COUNTER_NAME = T3.PARTY_NAME AND T3.PARTY_ID IS NULL
( T1.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR T1.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
T1.COUNTER_ID = #{initValue}
And T2.IS_ASSTE_MANAGER = #{isAssteManager}

SELECT T1.COUNTER_ID id, T1.COUNTER_NAME text FROM MST_COUNTER_PARTY T1 INNER JOIN MST_CUSTOMER_INFO T2 ON T1.LINK_ID = T2.CUSTOMER_ID INNER JOIN MST_CUSTOMER_INFO_ADD T3 ON T2.CUSTOMER_ID = T3.CUSTOMER_ID
( T1.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR T1.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
T3.INSITITUTE_CODE = #{initValue}

SELECT mcp.counter_id counterId FROM MST_COUNTER_PARTY mcp WHERE EXISTS (
SELECT 1 FROM MST_COUNTER_PARTY mcp2 WHERE mcp.COUNTER_name = mcp2.COUNTER_name and
counter_id = #{counterId}
)

SELECT distinct MST_CFETS_CUSTOMER_TRADER.TRADER_ID id, MST_CFETS_CUSTOMER_TRADER.TRADER_NAME text, MST_CFETS_CUSTOMER_TRADER.MPARTY_ID parentId FROM (SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID, MST_CFETS_CUSTOMER_TRADER.TRADER_NAME, MST_CFETS_CUSTOMER_TRADER.MPARTY_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN( SELECT nvl(t2.mparty_id,t1.party_id) PARTY_ID from MST_COUNTER_PARTY t3 inner join MST_CFETS_CUSTOMER_INFO t1 on T3.COUNTER_NAME = T1.PARTY_NAME LEFT JOIN MST_CFETS_CUSTOMER_RELA t2 on t1.party_id = t2.sparty_id WHERE 1 = 1
AND t3.COUNTER_ID = #{counterId}
) t3 on MST_CFETS_CUSTOMER_TRADER.PARTY_ID = t3.PARTY_ID WHERE 1 = 1
) MST_CFETS_CUSTOMER_TRADER
AND (MST_CFETS_CUSTOMER_TRADER.TRADER_ID like concat('%',concat(#{param},'%')) or MST_CFETS_CUSTOMER_TRADER.TRADER_NAME like concat('%',concat(#{param},'%')))
AND (MST_CFETS_CUSTOMER_TRADER.TRADER_ID like concat('%',concat(#{search},'%')) or MST_CFETS_CUSTOMER_TRADER.TRADER_NAME like concat('%',concat(#{search},'%')))
AND MST_CFETS_CUSTOMER_TRADER.TRADER_ID = #{initValue}
